}
.editorial-card p { font-size: .875rem; color: var(--color-ink-muted); line-height: 1.55; }
.editorial-card-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 1rem;
  padding-top: .75rem;
  border-top: 1px solid var(--color-surface-sunken);
}
.editorial-author { font-size: .8rem; color: var(--color-ink-subtle); }
.editorial-date { font-size: .8rem; color: var(--color-ink-subtle); }

/* ============================================
   TRUST BAR
   ============================================ */
.trust-bar {
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
  padding: 1.75rem 1.5rem;
  margin: 4.5rem 0;
}
.trust-bar-inner {
  max-width: 1280px;
  margin: 0 auto;
  display: flex;
  gap: 2rem;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
}
.trust-item {
  display: flex;
  align-items: center;
  gap: .75rem;
  flex: 1;
  min-width: 180px;
  max-width: 280px;
}
.trust-icon {
  width: 44px; height: 44px;
  background: var(--color-accent-light);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
