}
.trust-text strong {
  display: block;
  font-size: .9rem;
  font-weight: 700;
  color: var(--color-ink);
}
.trust-text span {
  font-size: .8rem;
  color: var(--color-ink-subtle);
}

/* ============================================
   NEWSLETTER
   ============================================ */
.newsletter-section {
  background: linear-gradient(135deg, var(--color-accent) 0%, #7c3aed 100%);
