}
.newsletter-status {
  margin-top: 1rem;
  font-size: .875rem;
  color: rgba(255,255,255,.9);
  min-height: 1.4em;
}

/* ============================================
   FOOTER
   ============================================ */
.site-footer {
  background: var(--color-ink);
  color: rgba(255,255,255,.7);
  padding: 3rem 1.5rem 1.5rem;
}
.footer-inner {
  max-width: 1280px;
