  .btn-cta, .btn-primary, .btn-add-cart, .btn-deal, .btn-newsletter {
    forced-color-adjust: none;
    background: ButtonText;
    color: ButtonFace;
    border: 1px solid ButtonText;
  }
  .product-card, .deal-card, .editorial-card {
    border: 1px solid ButtonText;
  }
  .hero-visual, .promo-banner {
    forced-color-adjust: auto;
  }
  .skip-link { forced-color-adjust: none; }
}
