/* ============================================
   LUMA — Ecommerce Home Page Styles
   ============================================ */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-ink: #0f0f11;
  --color-ink-muted: #4a4a56;
  --color-ink-subtle: #6e6e80;
  --color-surface: #ffffff;
  --color-surface-raised: #f7f7f9;
  --color-surface-sunken: #efeff3;
  --color-border: #dddde6;
  --color-accent: #5b4cff;
  --color-accent-hover: #4438e0;
  --color-accent-light: #ede9ff;
  --color-deal: #e63946;
  --color-deal-light: #fdedef;
  --color-success: #2d9e5f;
  --color-badge-new: #0a7ea4;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-pill: 999px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,.10), 0 2px 6px rgba(0,0,0,.06);
  --shadow-lg: 0 12px 32px rgba(0,0,0,.12), 0 4px 10px rgba(0,0,0,.06);
  --font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --transition: 0.18s ease;
}

html { font-size: 100%; scroll-behavior: smooth; }
body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-ink);
  background: var(--color-surface);
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; }
ul, ol { list-style: none; }
a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; border: none; background: none; }

/* --- Skip link --- */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  padding: .5rem 1rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-weight: 600;
  font-size: .9rem;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* --- Screen-reader-only utility --- */
.sr-only {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

/* ============================================
   HEADER / NAV
   ============================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: .75rem 1.5rem;
  display: flex;
  align-items: center;
  gap: 2rem;
}

/* Logo */
.site-logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  text-decoration: none;
  flex-shrink: 0;
}
.logo-mark {
  width: 36px; height: 36px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
  color: #fff;
  font-weight: 800;
  font-size: 1.1rem;
  letter-spacing: -.04em;
}
.logo-name {
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -.04em;
  color: var(--color-ink);
}

/* Primary nav */
.primary-nav { flex: 1; }
.primary-nav ul {
  display: flex;
  gap: .25rem;
  align-items: center;
}
.primary-nav a,
.primary-nav button {
  padding: .4rem .8rem;
  border-radius: var(--radius-sm);
  font-size: .9375rem;
  font-weight: 500;
  color: var(--color-ink-muted);
  transition: background var(--transition), color var(--transition);
}
.primary-nav a:hover,
.primary-nav button:hover,
.primary-nav a:focus-visible,
.primary-nav button:focus-visible {
  background: var(--color-surface-raised);
  color: var(--color-ink);
}
.primary-nav a[aria-current="page"] {
  color: var(--color-accent);
  background: var(--color-accent-light);
  font-weight: 600;
}

/* Sub-nav dropdown */
.nav-item { position: relative; }
.nav-trigger { display: flex; align-items: center; gap: .3rem; }
.nav-trigger svg { width: 14px; height: 14px; transition: transform var(--transition); }
.nav-trigger[aria-expanded="true"] svg { transform: rotate(180deg); }

.sub-nav {
  position: absolute;
  top: calc(100% + .5rem);
  left: 0;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  min-width: 180px;
  padding: .5rem;
  display: flex;
  flex-direction: column;
  gap: .125rem;
}
.sub-nav[hidden] { display: none; }
.sub-nav a {
  padding: .45rem .75rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  display: block;
}
.sub-nav a:hover,
.sub-nav a:focus-visible {
  background: var(--color-surface-raised);
  color: var(--color-accent);
}

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: .5rem;
  flex-shrink: 0;
}
.icon-btn {
  position: relative;
  padding: .5rem;
  border-radius: var(--radius-sm);
  color: var(--color-ink-muted);
  transition: background var(--transition), color var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
}
.icon-btn:hover, .icon-btn:focus-visible {
  background: var(--color-surface-raised);
  color: var(--color-ink);
}
.icon-btn svg { width: 22px; height: 22px; }
.cart-badge {
  position: absolute;
  top: 2px; right: 2px;
  background: var(--color-accent);
  color: #fff;
  font-size: .625rem;
  font-weight: 700;
  line-height: 1;
  padding: 2px 4px;
  border-radius: var(--radius-pill);
  min-width: 16px;
  text-align: center;
}

.btn-primary {
  padding: .5rem 1.1rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: .9rem;
  transition: background var(--transition), box-shadow var(--transition);
}
.btn-primary:hover, .btn-primary:focus-visible {
  background: var(--color-accent-hover);
  box-shadow: 0 0 0 3px rgba(91,76,255,.3);
}

/* Mobile menu toggle */
.mobile-menu-btn {
  display: none;
  padding: .5rem;
  border-radius: var(--radius-sm);
  color: var(--color-ink-muted);
}
.mobile-menu-btn:hover, .mobile-menu-btn:focus-visible {
  background: var(--color-surface-raised);
  color: var(--color-ink);
}
.mobile-menu-btn svg { width: 24px; height: 24px; }

/* Mobile nav panel */
.mobile-nav-panel {
  display: none;
  padding: 1rem 1.5rem 1.5rem;
  border-top: 1px solid var(--color-border);
  background: var(--color-surface);
}
.mobile-nav-panel.is-open { display: block; }
.mobile-nav-panel ul { display: flex; flex-direction: column; gap: .25rem; }
.mobile-nav-panel a {
  display: block;
  padding: .6rem .75rem;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-ink-muted);
}
.mobile-nav-panel a:hover, .mobile-nav-panel a:focus-visible {
  background: var(--color-surface-raised);
  color: var(--color-ink);
}

/* Focus-visible globally */
:focus-visible {
  outline: 2.5px solid var(--color-accent);
  outline-offset: 2px;
}
:focus:not(:focus-visible) { outline: none; }

/* ============================================
   PROMO BANNER
   ============================================ */
.promo-banner {
  background: var(--color-accent);
  color: #fff;
  text-align: center;
  padding: .6rem 1rem;
  font-size: .875rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
}
.promo-banner a {
  color: #fff;
  text-decoration: underline;
  text-underline-offset: 2px;
  font-weight: 600;
}
.promo-banner a:hover { opacity: .85; }
.promo-close {
  position: absolute;
  right: 1rem;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(255,255,255,.8);
  padding: .25rem;
  border-radius: var(--radius-sm);
}
.promo-close:hover { color: #fff; background: rgba(255,255,255,.15); }
.promo-close svg { width: 16px; height: 16px; }

/* ============================================
   MAIN LAYOUT
   ============================================ */
main { outline: none; }

.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

section + section { margin-top: 4.5rem; }

/* ============================================
   HERO
   ============================================ */
.hero {
  padding: 3rem 1.5rem;
  max-width: 1280px;
  margin: 2.5rem auto 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
}

.hero-content { max-width: 520px; }
.hero-eyebrow {
  display: inline-block;
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-accent);
  background: var(--color-accent-light);
  padding: .25rem .75rem;
  border-radius: var(--radius-pill);
  margin-bottom: 1.25rem;
}
.hero h1 {
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -.03em;
  color: var(--color-ink);
  margin-bottom: 1rem;
}
.hero-desc {
  font-size: 1.0625rem;
  color: var(--color-ink-muted);
  margin-bottom: 2rem;
  max-width: 440px;
}
.hero-actions {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}
.btn-secondary {
  padding: .65rem 1.4rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: .9375rem;
  border: 1.5px solid var(--color-border);
  color: var(--color-ink);
  transition: background var(--transition), border-color var(--transition);
  display: inline-flex;
  align-items: center;
  gap: .4rem;
}
.btn-secondary:hover, .btn-secondary:focus-visible {
  background: var(--color-surface-raised);
  border-color: var(--color-ink-subtle);
}
.btn-cta {
  padding: .65rem 1.4rem;
  background: var(--color-ink);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: .9375rem;
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  transition: background var(--transition), box-shadow var(--transition);
}
.btn-cta:hover, .btn-cta:focus-visible {
  background: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(91,76,255,.25);
}

.hero-visual {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #f0eeff 0%, #e5f0ff 50%, #faf0ff 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}
.hero-visual-inner {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  padding: 1.5rem;
  width: 100%;
}
.hero-product-preview {
  background: #fff;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  padding: 1rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .5rem;
}
.hero-product-preview .product-emoji {
  font-size: 2.5rem;
  line-height: 1;
}
.hero-product-preview .product-mini-name {
  font-size: .75rem;
  font-weight: 600;
  color: var(--color-ink-muted);
  text-align: center;
}
.hero-product-preview .product-mini-price {
  font-size: .9rem;
  font-weight: 700;
  color: var(--color-ink);
}
.hero-badge {
  position: absolute;
  top: 1.25rem;
  right: 1.25rem;
  background: var(--color-deal);
  color: #fff;
  font-size: .75rem;
  font-weight: 700;
  padding: .3rem .7rem;
  border-radius: var(--radius-pill);
}

/* ============================================
   SECTION HEADER
   ============================================ */
.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 1.75rem;
  gap: 1rem;
  flex-wrap: wrap;
}
.section-title {
  font-size: 1.625rem;
  font-weight: 800;
  letter-spacing: -.025em;
  color: var(--color-ink);
}
.section-link {
  font-size: .9rem;
  font-weight: 600;
  color: var(--color-accent);
  display: inline-flex;
  align-items: center;
  gap: .25rem;
  border-radius: var(--radius-sm);
  padding: .2rem .4rem;
  margin: -.2rem -.4rem;
  transition: background var(--transition);
}
.section-link:hover, .section-link:focus-visible {
  background: var(--color-accent-light);
}
.section-link svg { width: 16px; height: 16px; }

/* ============================================
   PRODUCT GRID
   ============================================ */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
}
.product-card:hover { box-shadow: var(--shadow-md); }

@media (prefers-reduced-motion: no-preference) {
  .product-card:hover { transform: translateY(-2px); }
}

.product-img-wrap {
  aspect-ratio: 1;
  background: var(--color-surface-raised);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4.5rem;
  position: relative;
  overflow: hidden;
}
.product-img-wrap img {
  width: 100%; height: 100%;
  object-fit: cover;
}
.product-badge {
  position: absolute;
  top: .75rem; left: .75rem;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: .2rem .55rem;
  border-radius: var(--radius-pill);
}
.badge-new { background: var(--color-badge-new); color: #fff; }
.badge-sale { background: var(--color-deal); color: #fff; }
.badge-popular { background: var(--color-success); color: #fff; }

.product-body { padding: 1rem; flex: 1; display: flex; flex-direction: column; }
.product-category {
  font-size: .75rem;
  font-weight: 600;
  color: var(--color-ink-subtle);
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: .3rem;
}
.product-name {
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-ink);
  line-height: 1.3;
  margin-bottom: .5rem;
}
.product-name a {
  text-decoration: none;
  color: inherit;
  border-radius: 2px;
}
.product-name a:hover { color: var(--color-accent); }
.product-name a::after {
  content: '';
  display: block;
  position: absolute;
  inset: 0;
}
.product-card { position: relative; }
.product-rating {
  display: flex;
  align-items: center;
  gap: .3rem;
  margin-bottom: .75rem;
}
.stars { color: #f59e0b; font-size: .85rem; letter-spacing: -.02em; }
.rating-count { font-size: .8rem; color: var(--color-ink-subtle); }
.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: .75rem;
  border-top: 1px solid var(--color-surface-sunken);
  gap: .5rem;
}
.product-price { display: flex; align-items: baseline; gap: .4rem; }
.price-current {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--color-ink);
}
.price-original {
  font-size: .85rem;
  color: var(--color-ink-subtle);
  text-decoration: line-through;
}
.btn-add-cart {
  flex-shrink: 0;
  padding: .45rem .85rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-size: .8375rem;
  font-weight: 600;
  transition: background var(--transition), box-shadow var(--transition);
  position: relative;
  z-index: 1;
}
.btn-add-cart:hover, .btn-add-cart:focus-visible {
  background: var(--color-accent-hover);
  box-shadow: 0 0 0 3px rgba(91,76,255,.25);
}

/* Wishlist button */
.btn-wishlist {
  position: absolute;
  top: .75rem;
  right: .75rem;
  z-index: 1;
  padding: .4rem;
  background: rgba(255,255,255,.88);
  border-radius: var(--radius-sm);
  color: var(--color-ink-muted);
  backdrop-filter: blur(4px);
  transition: background var(--transition), color var(--transition);
  line-height: 0;
}
.btn-wishlist:hover, .btn-wishlist:focus-visible {
  background: #fff;
  color: var(--color-deal);
}
.btn-wishlist svg { width: 18px; height: 18px; }
.btn-wishlist[aria-pressed="true"] { color: var(--color-deal); }

/* ============================================
   DEALS SECTION
   ============================================ */
.deals-section { background: var(--color-surface-raised); border-radius: var(--radius-lg); padding: 2.5rem 2rem; }

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.25rem;
}

.deal-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition);
}
.deal-card:hover { box-shadow: var(--shadow-md); }

.deal-img-wrap {
  aspect-ratio: 16/9;
  background: linear-gradient(135deg, #fff0f2, #ffd6da);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
  position: relative;
}
.deal-discount-badge {
  position: absolute;
  bottom: .75rem;
  left: .75rem;
  background: var(--color-deal);
  color: #fff;
  font-size: .8rem;
  font-weight: 800;
  padding: .3rem .65rem;
  border-radius: var(--radius-pill);
}

.deal-body { padding: 1.25rem; flex: 1; display: flex; flex-direction: column; }
.deal-name {
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--color-ink);
  margin-bottom: .3rem;
}
.deal-desc { font-size: .875rem; color: var(--color-ink-muted); margin-bottom: 1rem; }

.deal-timer {
  display: flex;
  gap: .4rem;
  align-items: center;
  margin-bottom: 1rem;
}
.timer-label { font-size: .75rem; color: var(--color-ink-subtle); font-weight: 600; }
.timer-display {
  display: flex;
  gap: .2rem;
  align-items: center;
}
.timer-unit {
  background: var(--color-ink);
  color: #fff;
  border-radius: 4px;
  padding: .1rem .35rem;
  font-size: .8rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  min-width: 24px;
  text-align: center;
}
.timer-sep { color: var(--color-ink-muted); font-weight: 700; font-size: .8rem; }

.deal-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  gap: .75rem;
}
.deal-price { display: flex; align-items: baseline; gap: .4rem; }
.deal-price-current { font-size: 1.25rem; font-weight: 800; color: var(--color-deal); }
.deal-price-original { font-size: .9rem; color: var(--color-ink-subtle); text-decoration: line-through; }

.btn-deal {
  padding: .5rem 1.1rem;
  background: var(--color-deal);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: .875rem;
  transition: background var(--transition), box-shadow var(--transition);
  white-space: nowrap;
  position: relative;
  z-index: 1;
}
.btn-deal:hover, .btn-deal:focus-visible {
  background: #c42e39;
  box-shadow: 0 0 0 3px rgba(230,57,70,.25);
}

/* ============================================
   CATEGORY STRIP
   ============================================ */
.category-strip {
  display: flex;
  gap: .75rem;
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: .25rem;
}
.category-strip::-webkit-scrollbar { display: none; }

.category-pill {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .6rem 1.2rem;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-pill);
  font-size: .875rem;
  font-weight: 600;
  white-space: nowrap;
  color: var(--color-ink-muted);
  transition: background var(--transition), border-color var(--transition), color var(--transition);
  cursor: pointer;
  flex-shrink: 0;
}
.category-pill:hover, .category-pill:focus-visible {
  background: var(--color-accent-light);
  border-color: var(--color-accent);
  color: var(--color-accent);
}
.category-pill[aria-pressed="true"] {
  background: var(--color-accent);
  border-color: var(--color-accent);
  color: #fff;
}
.category-emoji { font-size: 1.1rem; line-height: 1; }

/* ============================================
   EDITORIAL SECTION
   ============================================ */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

.editorial-featured {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  background: var(--color-ink);
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 320px;
}
.editorial-featured-img {
  background: linear-gradient(135deg, #1a1a3e 0%, #2d1b69 50%, #4c1d95 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 8rem;
  padding: 2rem;
}
.editorial-featured-body {
  padding: 2.5rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  color: #fff;
}
.editorial-tag {
  display: inline-block;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: rgba(255,255,255,.6);
  margin-bottom: 1rem;
}
.editorial-featured-body h3 {
  font-size: 1.625rem;
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -.02em;
  margin-bottom: .75rem;
}
.editorial-featured-body p {
  font-size: .9375rem;
  color: rgba(255,255,255,.7);
  line-height: 1.6;
  margin-bottom: 1.5rem;
}
.btn-editorial-light {
  align-self: flex-start;
  padding: .55rem 1.2rem;
  background: rgba(255,255,255,.15);
  color: #fff;
  border: 1.5px solid rgba(255,255,255,.3);
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: .875rem;
  transition: background var(--transition), border-color var(--transition);
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  position: relative;
  z-index: 1;
}
.btn-editorial-light:hover, .btn-editorial-light:focus-visible {
  background: rgba(255,255,255,.25);
  border-color: rgba(255,255,255,.5);
}
.btn-editorial-light::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: var(--radius-sm);
}

.editorial-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition);
  position: relative;
}
.editorial-card:hover { box-shadow: var(--shadow-md); }
.editorial-card-img {
  aspect-ratio: 16/9;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
}
.editorial-card-img-1 { background: linear-gradient(135deg, #ecfdf5, #d1fae5); }
.editorial-card-img-2 { background: linear-gradient(135deg, #eff6ff, #dbeafe); }
.editorial-card-body { padding: 1.25rem; flex: 1; display: flex; flex-direction: column; }
.editorial-card-tag {
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: .5rem;
}
.editorial-card h3 {
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--color-ink);
  line-height: 1.3;
  margin-bottom: .5rem;
}
.editorial-card h3 a {
  text-decoration: none;
  color: inherit;
  border-radius: 2px;
}
.editorial-card h3 a:hover { color: var(--color-accent); }
.editorial-card h3 a::after {
  content: '';
  position: absolute;
  inset: 0;
}
.editorial-card p { font-size: .875rem; color: var(--color-ink-muted); line-height: 1.55; }
.editorial-card-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 1rem;
  padding-top: .75rem;
  border-top: 1px solid var(--color-surface-sunken);
}
.editorial-author { font-size: .8rem; color: var(--color-ink-subtle); }
.editorial-date { font-size: .8rem; color: var(--color-ink-subtle); }

/* ============================================
   TRUST BAR
   ============================================ */
.trust-bar {
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
  padding: 1.75rem 1.5rem;
  margin: 4.5rem 0;
}
.trust-bar-inner {
  max-width: 1280px;
  margin: 0 auto;
  display: flex;
  gap: 2rem;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
}
.trust-item {
  display: flex;
  align-items: center;
  gap: .75rem;
  flex: 1;
  min-width: 180px;
  max-width: 280px;
}
.trust-icon {
  width: 44px; height: 44px;
  background: var(--color-accent-light);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1.3rem;
}
.trust-text strong {
  display: block;
  font-size: .9rem;
  font-weight: 700;
  color: var(--color-ink);
}
.trust-text span {
  font-size: .8rem;
  color: var(--color-ink-subtle);
}

/* ============================================
   NEWSLETTER
   ============================================ */
.newsletter-section {
  background: linear-gradient(135deg, var(--color-accent) 0%, #7c3aed 100%);
  border-radius: var(--radius-lg);
  padding: 3rem 2rem;
  text-align: center;
  color: #fff;
  margin-bottom: 4.5rem;
}
.newsletter-section h2 {
  font-size: 1.875rem;
  font-weight: 800;
  letter-spacing: -.025em;
  margin-bottom: .75rem;
}
.newsletter-section p {
  font-size: 1rem;
  color: rgba(255,255,255,.8);
  margin-bottom: 2rem;
  max-width: 440px;
  margin-left: auto;
  margin-right: auto;
}
.newsletter-form {
  display: flex;
  gap: .75rem;
  max-width: 480px;
  margin: 0 auto;
  flex-wrap: wrap;
  justify-content: center;
}
.newsletter-input-wrap { flex: 1; min-width: 200px; }
.newsletter-input-wrap label {
  display: block;
  font-size: .85rem;
  font-weight: 600;
  margin-bottom: .4rem;
  color: rgba(255,255,255,.85);
  text-align: left;
}
.newsletter-input {
  width: 100%;
  padding: .65rem 1rem;
  border-radius: var(--radius-sm);
  border: 1.5px solid rgba(255,255,255,.3);
  background: rgba(255,255,255,.12);
  color: #fff;
  font: inherit;
  font-size: .9375rem;
  transition: border-color var(--transition), background var(--transition);
}
.newsletter-input::placeholder { color: rgba(255,255,255,.5); }
.newsletter-input:focus-visible {
  outline: 2.5px solid #fff;
  outline-offset: 1px;
  border-color: transparent;
  background: rgba(255,255,255,.2);
}
.btn-newsletter {
  padding: .65rem 1.4rem;
  background: #fff;
  color: var(--color-accent);
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: .9375rem;
  transition: background var(--transition), box-shadow var(--transition);
  align-self: flex-end;
  margin-bottom: 0;
}
.btn-newsletter:hover, .btn-newsletter:focus-visible {
  background: rgba(255,255,255,.92);
  box-shadow: 0 0 0 3px rgba(255,255,255,.4);
}
.newsletter-status {
  margin-top: 1rem;
  font-size: .875rem;
  color: rgba(255,255,255,.9);
  min-height: 1.4em;
}

/* ============================================
   FOOTER
   ============================================ */
.site-footer {
  background: var(--color-ink);
  color: rgba(255,255,255,.7);
  padding: 3rem 1.5rem 1.5rem;
}
.footer-inner {
  max-width: 1280px;
  margin: 0 auto;
}
.footer-top {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 3rem;
}
.footer-brand { max-width: 280px; }
.footer-logo {
  display: flex;
  align-items: center;
  gap: .6rem;
  text-decoration: none;
  margin-bottom: 1rem;
}
.footer-logo-mark {
  width: 34px; height: 34px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
  color: #fff;
  font-weight: 800;
  font-size: 1rem;
}
.footer-logo-name {
  font-size: 1.1rem;
  font-weight: 800;
  letter-spacing: -.04em;
  color: #fff;
}
.footer-tagline {
  font-size: .875rem;
  line-height: 1.6;
  margin-bottom: 1.25rem;
}
.footer-social {
  display: flex;
  gap: .5rem;
}
.social-link {
  width: 36px; height: 36px;
  background: rgba(255,255,255,.08);
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
  color: rgba(255,255,255,.7);
  transition: background var(--transition), color var(--transition);
}
.social-link:hover, .social-link:focus-visible {
  background: rgba(255,255,255,.15);
  color: #fff;
}
.social-link svg { width: 18px; height: 18px; }

.footer-col h3 {
  font-size: .875rem;
  font-weight: 700;
  color: #fff;
  margin-bottom: 1rem;
  letter-spacing: .01em;
}
.footer-col ul { display: flex; flex-direction: column; gap: .5rem; }
.footer-col a {
  font-size: .875rem;
  color: rgba(255,255,255,.6);
  border-radius: 3px;
  transition: color var(--transition);
}
.footer-col a:hover, .footer-col a:focus-visible { color: #fff; }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  padding-top: 1.5rem;
  border-top: 1px solid rgba(255,255,255,.1);
}
.footer-legal { font-size: .8rem; color: rgba(255,255,255,.4); }
.footer-legal-links {
  display: flex;
  gap: 1.25rem;
}
.footer-legal-links a {
  font-size: .8rem;
  color: rgba(255,255,255,.4);
  border-radius: 3px;
  transition: color var(--transition);
}
.footer-legal-links a:hover, .footer-legal-links a:focus-visible { color: rgba(255,255,255,.7); }

/* ============================================
   RESPONSIVE
   ============================================ */
@media (max-width: 900px) {
  .hero { grid-template-columns: 1fr; }
  .hero-visual { display: none; }
  .editorial-featured { grid-template-columns: 1fr; }
  .editorial-featured-img { aspect-ratio: 16/9; font-size: 5rem; }
  .footer-top { grid-template-columns: 1fr 1fr; gap: 2rem; }
  .footer-brand { grid-column: 1 / -1; max-width: none; }
}

@media (max-width: 768px) {
  .primary-nav { display: none; }
  .mobile-menu-btn { display: flex; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-featured { grid-column: auto; }
  section + section { margin-top: 3rem; }
}

