  font-weight: 800;
  font-size: 1.1rem;
  letter-spacing: -.04em;
}
.logo-name {
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -.04em;
  color: var(--color-ink);
}

/* Primary nav */
.primary-nav { flex: 1; }
.primary-nav ul {
  display: flex;
  gap: .25rem;
  align-items: center;
}
.primary-nav a,
.primary-nav button {
