+  padding: .65rem 1rem;
+  border-radius: var(--radius-sm);
+  border: 1.5px solid rgba(255,255,255,.3);
+  background: rgba(255,255,255,.12);
+  color: #fff;
+  font: inherit;
+  font-size: .9375rem;
+  transition: border-color var(--transition), background var(--transition);
+}
+.newsletter-input::placeholder { color: rgba(255,255,255,.5); }
+.newsletter-input:focus-visible {
+  outline: 2.5px solid #fff;
+  outline-offset: 1px;
+  border-color: transparent;
+  background: rgba(255,255,255,.2);
+}
+.btn-newsletter {
+  padding: .65rem 1.4rem;
+  background: #fff;
+  color: var(--color-accent);
+  border-radius: var(--radius-sm);
+  font-weight: 700;
+  font-size: .9375rem;
+  transition: background var(--transition), box-shadow var(--transition);
+  align-self: flex-end;
+  margin-bottom: 0;
+}
+.btn-newsletter:hover, .btn-newsletter:focus-visible {
+  background: rgba(255,255,255,.92);
+  box-shadow: 0 0 0 3px rgba(255,255,255,.4);
+}
+.newsletter-status {
+  margin-top: 1rem;
+  font-size: .875rem;
+  color: rgba(255,255,255,.9);
+  min-height: 1.4em;
+}
+
+/* ============================================
+   FOOTER
+   ============================================ */
+.site-footer {
+  background: var(--color-ink);
+  color: rgba(255,255,255,.7);
+  padding: 3rem 1.5rem 1.5rem;
+}
+.footer-inner {
+  max-width: 1280px;
+  margin: 0 auto;
+}
+.footer-top {
+  display: grid;
+  grid-template-columns: 1.5fr repeat(3, 1fr);
+  gap: 3rem;
+  margin-bottom: 3rem;
+}
+.footer-brand { max-width: 280px; }
+.footer-logo {
+  display: flex;
+  align-items: center;
+  gap: .6rem;
+  text-decoration: none;
+  margin-bottom: 1rem;
+}
+.footer-logo-mark {
+  width: 34px; height: 34px;
+  background: var(--color-accent);
+  border-radius: var(--radius-sm);
+  display: grid;
+  place-items: center;
+  color: #fff;
+  font-weight: 800;
+  font-size: 1rem;
+}
+.footer-logo-name {
+  font-size: 1.1rem;
+  font-weight: 800;
+  letter-spacing: -.04em;
+  color: #fff;
+}
+.footer-tagline {
+  font-size: .875rem;
+  line-height: 1.6;
+  margin-bottom: 1.25rem;
+}
+.footer-social {
+  display: flex;
+  gap: .5rem;
+}
+.social-link {
+  width: 36px; height: 36px;
+  background: rgba(255,255,255,.08);
+  border-radius: var(--radius-sm);
+  display: grid;
+  place-items: center;
+  color: rgba(255,255,255,.7);
+  transition: background var(--transition), color var(--transition);
+}
+.social-link:hover, .social-link:focus-visible {
+  background: rgba(255,255,255,.15);
+  color: #fff;
+}
+.social-link svg { width: 18px; height: 18px; }
+
+.footer-col h3 {
+  font-size: .875rem;
+  font-weight: 700;
+  color: #fff;
+  margin-bottom: 1rem;
+  letter-spacing: .01em;
+}
+.footer-col ul { display: flex; flex-direction: column; gap: .5rem; }
+.footer-col a {
+  font-size: .875rem;
+  color: rgba(255,255,255,.6);
+  border-radius: 3px;
+  transition: color var(--transition);
+}
+.footer-col a:hover, .footer-col a:focus-visible { color: #fff; }
+
+.footer-bottom {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  flex-wrap: wrap;
+  gap: 1rem;
+  padding-top: 1.5rem;
+  border-top: 1px solid rgba(255,255,255,.1);
+}
+.footer-legal { font-size: .8rem; color: rgba(255,255,255,.4); }
+.footer-legal-links {
+  display: flex;
+  gap: 1.25rem;
+}
+.footer-legal-links a {
+  font-size: .8rem;
+  color: rgba(255,255,255,.4);
+  border-radius: 3px;
+  transition: color var(--transition);
+}
+.footer-legal-links a:hover, .footer-legal-links a:focus-visible { color: rgba(255,255,255,.7); }
+
+/* ============================================
+   RESPONSIVE
+   ============================================ */
+@media (max-width: 900px) {
+  .hero { grid-template-columns: 1fr; }
+  .hero-visual { display: none; }
+  .editorial-featured { grid-template-columns: 1fr; }
+  .editorial-featured-img { aspect-ratio: 16/9; font-size: 5rem; }
+  .footer-top { grid-template-columns: 1fr 1fr; gap: 2rem; }
+  .footer-brand { grid-column: 1 / -1; max-width: none; }
+}
+
+@media (max-width: 768px) {
+  .primary-nav { display: none; }
+  .mobile-menu-btn { display: flex; }
+  .editorial-grid { grid-template-columns: 1fr; }
+  .editorial-featured { grid-column: auto; }
+  section + section { margin-top: 3rem; }
+}
+
+@media (max-width: 600px) {
+  .header-inner { gap: 1rem; }
+  .hero { padding: 2rem 1.25rem; }
+  .hero h1 { font-size: 2rem; }
+  .deals-grid { grid-template-columns: 1fr; }
+  .footer-top { grid-template-columns: 1fr; }
+  .footer-bottom { flex-direction: column; align-items: flex-start; }
+  .newsletter-form { flex-direction: column; }
+  .btn-newsletter { align-self: stretch; text-align: center; }
+  .trust-bar-inner { flex-direction: column; align-items: flex-start; }
+  .trust-item { max-width: none; }
+}
+
+/* ============================================
+   REDUCED MOTION
+   ============================================ */
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after {
+    animation-duration: .01ms !important;
+    animation-iteration-count: 1 !important;
+    transition-duration: .01ms !important;
+    scroll-behavior: auto !important;
+  }
+}
+
+/* ============================================
+   FORCED COLORS (High Contrast)
+   ============================================ */
+@media (forced-colors: active) {
+  .btn-cta, .btn-primary, .btn-add-cart, .btn-deal, .btn-newsletter {
+    forced-color-adjust: none;
+    background: ButtonText;
+    color: ButtonFace;
+    border: 1px solid ButtonText;
+  }
+  .product-card, .deal-card, .editorial-card {
+    border: 1px solid ButtonText;
+  }
+  .hero-visual, .promo-banner {
+    forced-color-adjust: auto;
+  }
+  .skip-link { forced-color-adjust: none; }
+}
+
')

