(function () {
  "use strict";

  /* ---- Promo Banner ---- */
  const promoBanner = document.getElementById("promo-banner");
  const promoClose = document.getElementById("promo-close");
  if (promoClose && promoBanner) {
    promoClose.addEventListener("click", () => {
      promoBanner.hidden = true;
    });
  }

  /* ---- Mobile Nav ---- */
  const mobileMenuBtn = document.getElementById("mobile-menu-btn");
  const mobileNavPanel = document.getElementById("mobile-nav-panel");
  if (mobileMenuBtn && mobileNavPanel) {
    mobileMenuBtn.addEventListener("click", () => {
      const isOpen = mobileNavPanel.classList.toggle("is-open");
      mobileMenuBtn.setAttribute("aria-expanded", String(isOpen));
    });
    // Close on Escape
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && mobileNavPanel.classList.contains("is-open")) {
        mobileNavPanel.classList.remove("is-open");
        mobileMenuBtn.setAttribute("aria-expanded", "false");
        mobileMenuBtn.focus();
      }
    });
  }

  /* ---- Desktop Sub-nav Dropdowns ---- */
  const navTriggers = document.querySelectorAll(".nav-trigger");
  navTriggers.forEach((trigger) => {
    const subNav = trigger.nextElementSibling;
    if (!subNav) return;

    trigger.addEventListener("click", () => {
      const isExpanded = trigger.getAttribute("aria-expanded") === "true";
      // Close all others first
      navTriggers.forEach((t) => {
        if (t !== trigger) {
          t.setAttribute("aria-expanded", "false");
          const s = t.nextElementSibling;
          if (s) s.hidden = true;
        }
      });
      trigger.setAttribute("aria-expanded", String(!isExpanded));
      subNav.hidden = isExpanded;
      if (!isExpanded) {
        const firstLink = subNav.querySelector("a");
        if (firstLink) firstLink.focus();
      }
    });

    // Escape closes sub-nav
    subNav.addEventListener("keydown", (e) => {
      if (e.key === "Escape") {
        trigger.setAttribute("aria-expanded", "false");
        subNav.hidden = true;
        trigger.focus();
      }
    });
  });

  // Close dropdowns on outside click
  document.addEventListener("click", (e) => {
    if (!e.target.closest(".nav-item")) {
      navTriggers.forEach((t) => {
        t.setAttribute("aria-expanded", "false");
        const s = t.nextElementSibling;
        if (s) s.hidden = true;
      });
    }
  });

  /* ---- Category Pills (filter toggle) ---- */
  const categoryPills = document.querySelectorAll(".category-pill");
  categoryPills.forEach((pill) => {
    pill.addEventListener("click", () => {
      const isPressed = pill.getAttribute("aria-pressed") === "true";
      // Deselect all, then select the clicked one (unless deselecting)
      categoryPills.forEach((p) => p.setAttribute("aria-pressed", "false"));
      if (!isPressed) pill.setAttribute("aria-pressed", "true");
    });
  });

  /* ---- Wishlist Buttons ---- */
  const wishlistBtns = document.querySelectorAll(".btn-wishlist");
  wishlistBtns.forEach((btn) => {
    btn.addEventListener("click", () => {
      const isPressed = btn.getAttribute("aria-pressed") === "true";
      btn.setAttribute("aria-pressed", String(!isPressed));
      const label = btn.closest("article")?.querySelector(".product-name a")?.textContent?.trim() || "item";
      const msg = isPressed ? `Removed ${label} from wishlist` : `Added ${label} to wishlist`;
      announceStatus(msg);
    });
  });

  /* ---- Add to Cart Buttons ---- */
  let cartCount = 3;
  const cartCountEl = document.getElementById("cart-count");
  const addCartBtns = document.querySelectorAll(".btn-add-cart, .btn-deal");
  addCartBtns.forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      cartCount++;
      if (cartCountEl) cartCountEl.textContent = cartCount;
      const productName = btn.getAttribute("aria-label")?.replace(/^(Add to cart|Shop deal):\s*/, "") || "item";
      announceStatus(`Added ${productName} to cart. Cart now has ${cartCount} items.`);
    });
  });

  /* ---- Newsletter Form ---- */
  const newsletterForm = document.getElementById("newsletter-form");
  const newsletterStatus = document.getElementById("newsletter-status");
  if (newsletterForm && newsletterStatus) {
    newsletterForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const emailInput = document.getElementById("newsletter-email");
      const email = emailInput?.value?.trim();
      if (!email) {
        newsletterStatus.textContent = "Please enter your email address.";
        newsletterStatus.setAttribute("role", "alert");
        emailInput?.focus();
        return;
      }
      newsletterStatus.textContent = "🎉 You're subscribed! Check your inbox for a welcome offer.";
      newsletterStatus.setAttribute("role", "status");
      newsletterForm.reset();
    });
  }

  /* ---- Countdown Timers ---- */
  const timers = document.querySelectorAll("[data-ends-at]");
  timers.forEach((el) => {
    const endsAt = parseInt(el.dataset.endsAt, 10);
    const hEl = el.querySelector("[data-timer-h]");
    const mEl = el.querySelector("[data-timer-m]");
    const sEl = el.querySelector("[data-timer-s]");
    if (!hEl || !mEl || !sEl) return;

    function update() {
      const now = Date.now();
      let diff = Math.max(0, endsAt - now);
      const h = Math.floor(diff / 3600000); diff -= h * 3600000;
      const m = Math.floor(diff / 60000); diff -= m * 60000;
      const s = Math.floor(diff / 1000);
      hEl.textContent = String(h).padStart(2, "0");
      mEl.textContent = String(m).padStart(2, "0");
      sEl.textContent = String(s).padStart(2, "0");
    }
    update();
    setInterval(update, 1000);
  });

  /* ---- Live Region for Status Announcements ---- */
  let liveRegion = document.getElementById("live-region");
  if (!liveRegion) {
    liveRegion = document.createElement("div");
    liveRegion.id = "live-region";
    liveRegion.setAttribute("role", "status");
    liveRegion.setAttribute("aria-live", "polite");
    liveRegion.setAttribute("aria-atomic", "true");
    liveRegion.className = "sr-only";
    document.body.appendChild(liveRegion);
  }

  function announceStatus(msg) {
    liveRegion.textContent = "";
    // Small delay ensures screen readers re-announce even identical messages
    requestAnimationFrame(() => {
      liveRegion.textContent = msg;
    });
  }
})();
