  const categoryPills = document.querySelectorAll(".category-pill");
  categoryPills.forEach((pill) => {
    pill.addEventListener("click", () => {
      const isPressed = pill.getAttribute("aria-pressed") === "true";
      // Deselect all, then select the clicked one (unless deselecting)
      categoryPills.forEach((p) => p.setAttribute("aria-pressed", "false"));
      if (!isPressed) pill.setAttribute("aria-pressed", "true");
    });
  });

