      announceStatus(msg);
    });
  });

  /* ---- Add to Cart Buttons ---- */
  let cartCount = 3;
  const cartCountEl = document.getElementById("cart-count");
  const addCartBtns = document.querySelectorAll(".btn-add-cart, .btn-deal");
  addCartBtns.forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      cartCount++;
      if (cartCountEl) cartCountEl.textContent = cartCount;
      const productName = btn.getAttribute("aria-label")?.replace(/^(Add to cart|Shop deal):\s*/, "") || "item";
      announceStatus(`Added ${productName} to cart. Cart now has ${cartCount} items.`);
