  const newsletterForm = document.getElementById("newsletter-form");
  const newsletterStatus = document.getElementById("newsletter-status");
  if (newsletterForm && newsletterStatus) {
    newsletterForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const emailInput = document.getElementById("newsletter-email");
      const email = emailInput?.value?.trim();
      if (!email) {
        newsletterStatus.textContent = "Please enter your email address.";
        newsletterStatus.setAttribute("role", "alert");
        emailInput?.focus();
        return;
      }
      newsletterStatus.textContent = "🎉 You're subscribed! Check your inbox for a welcome offer.";
      newsletterStatus.setAttribute("role", "status");
      newsletterForm.reset();
    });
  }

  /* ---- Countdown Timers ---- */
  const timers = document.querySelectorAll("[data-ends-at]");
  timers.forEach((el) => {
    const endsAt = parseInt(el.dataset.endsAt, 10);
    const hEl = el.querySelector("[data-timer-h]");
    const mEl = el.querySelector("[data-timer-m]");
    const sEl = el.querySelector("[data-timer-s]");
    if (!hEl || !mEl || !sEl) return;

    function update() {
      const now = Date.now();
      let diff = Math.max(0, endsAt - now);
      const h = Math.floor(diff / 3600000); diff -= h * 3600000;
      const m = Math.floor(diff / 60000); diff -= m * 60000;
      const s = Math.floor(diff / 1000);
      hEl.textContent = String(h).padStart(2, "0");
      mEl.textContent = String(m).padStart(2, "0");
      sEl.textContent = String(s).padStart(2, "0");
    }
    update();
    setInterval(update, 1000);
  });

