const b = await chromium.launch();
const page = await b.newPage();
await page.setContent(html, { waitUntil: 'load' });
await page.addScriptTag({ path: '/tmp/axe.min.js' });
const r = await page.evaluate(async () => await window.axe.run());
await b.close();

const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));
const fmt = v => ({
  id: v.id, impact: v.impact,
  nodes: v.nodes.map(n => ({ target: n.target, html: n.html.slice(0,200), fail: n.failureSummary }))
});
console.log(JSON.stringify({ wcag: wcag.map(fmt), bp: bp.map(fmt) }, null, 2));
process.exit(wcag.length > 0 ? 1 : 0);
EOF", hook_message=None, intention='Run axe via Playwright ESM', new_file_contents=None, path=None, paths=None, reason=None, server_name=None, subject=None, tool_args=None, tool_call_id='tooluse_ApoIsg1psfz2FBNbyPJqu1', tool_description=None, tool_name=None, tool_title=None, url=None, warning=None)

